-- Parte 3 de 3. Completa campos del "Informe general descriptivo" tomados de la hoja de Google Sheets:
--   Valoración del partido visto (val_partido), Valoración (valoracion) y observaciones de caracterización (car_obs_*).
-- Solo escribe donde el campo está vacío o tiene un valor que no es una opción válida del formulario.
-- Ejecuta las 3 partes (se pueden repetir sin problema).
update public.reports r
set data = r.data || v.patch::jsonb
from (values
('dc40e23b-c8c4-4877-a08c-0332a735b5c1','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE","car_obs_EXTREMO":"Jugador con capacidad fisica para atacar espacios y para ganar duelos, con una aceleracion y velocidad final importante, y una capacidad de salto bastante buena, puede jugar por ambos carriles exteriores y entiende muy bien en que momento atacar intervalos, puede asociarse tambien sin problema tanto por fuera como por dentro."}'),
('dc735f7c-8656-40c0-a9f4-341a22165e6a','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_LATERAL":"Ya tuvo su paso por el club, no fué lo esperado, quizá en otro contexto y con un DT que lo sepa potenciar, aún podría recuperar nivel y ser un jugador de confianza, por lo pronto no está pasando su mejor momento fútbolistico, habrá que seguir observando sin ser prioridad."}'),
('e0ed44d0-2097-4fa5-b6a1-e95a6efdde6b','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO"}'),
('e49c724e-8c0f-494a-9317-9472ae8f393d','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_EXTREMO":"Puede igualar el nivel actualmente de los jugadores actuales de la plantilla pero no los mejora y para proyección a futuro es descartable."}'),
('ebf22947-c4fc-40c4-9e08-ad1b136c14c9','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR"}'),
('f1c47028-f390-431c-ad22-cd9d9a4575ee','{"val_partido":"SIN VER","valoracion":"4.INTERESANTE","car_obs_EXTREMO":"ES UN EXTREMO CON MUCHA CALIDAD, MUY VELOZ. FUE TRANSFERIDO A QUERETARO DONDE SUFRIO UNA LESION GRAVE QUE LO TIENE ALEJADO DE LAS CANCHAS. SEGUN LOS ULTIMOS REPORTES SE ENCUENTRA PROXIMO A VOLVER A LA ACTIVIDAD EN CANCHA."}'),
('f1f632b4-72d4-4fa6-8e61-79a49422f512','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_PUNTA":"Delantero que busca hallarse espacios entre los centrales y buscar sorpresas para incomodar dentro del área, un perfil muy interesante tomando en cuenta su edad, es ecuatoriano, tiene paso por selección ecuatoriana en juveniles, actualmente no está siendo titular, el momento de su equipo tampoco lo ayuda, pero tiene un buen potencial pensando incluso a futuro. A seguirlo muy de cerca y tenerle consideración para el siguiente mercado."}'),
('f563786d-dac3-4861-9a89-99d1a8419112','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_MEDIOCENTRO":"Perfil de basta experiencia en el fútbol ecuatoriano, pero por edad totalmente descartable."}'),
('f5f5b3e5-af8d-43e0-8a8e-ebe7dab0152a','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_LATERAL":"Lateral que aporta bastante verticalidad, es rápido al espacio, fuerte físicamente para el choque cuerpo a cuerpo, no está fino en la toma de decisiones, al menos al momento de querer centrar, no es titular en su equipo, quizá está con falta de confianza, pero sin duda es un perfil que a nosotros nos encajaría bien, incluso pensando rejuvenecer esa zona del lateral derecho. A seguirlo de cerca observando."}'),
('fad217e8-cda0-4368-b773-b0a88fab0a0d','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO"}'),
('fb9c4641-b994-4c3f-923b-a6442f6593ee','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_PUNTA":"Ya tuvo su pasó por el fútbol ecuatoriano sin pena ni gloria, incluso por edad no es lo adecuado. Descarte."}'),
('fbfd9e03-ce8a-4366-9cc1-df4ca95a8f4f','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIAPUNTA":"Jugador experimentado dentro del fútbol ecuatoriano, por trayectoria perfil a tenerlo en consideración pero por presente fútbolistico no debe ser prioridad."}'),
('fcfd8a99-62d3-4628-8d1d-e235397029b1','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Central sólido en las coberturas, pero hay mejores opciones en el mercado. Seguir viendo"}'),
('00b79a57-68f8-4fdf-89ad-5cc38ff9952b','{"val_partido":"4. ALTA RELEVANCIA","car_obs_ARQUERO":"Arquero ágil de reacción para recomponerse, pero da muchos rebotes y para su edad no es un arquero diferencial o que mejore al actual arquero del club. Descarte."}'),
('053db1c6-317d-4ad9-8eee-f34206897f53','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR","car_obs_EXTREMO":"Fué el jugador más incisivo de su equipo el día de hoy, buscó siempre el duelo 1vs1 y en ocasiones salió airoso, casi siempre encara para afuera y tiene buen regate y algo de aceleración, pero por edad y en una posición que se necesita más dinámica para el fútbol ecuatoriano, es un perfil que hay que descartar."}'),
('064fdf2d-9e7f-4617-ae6f-93d4ee86cca2','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_INTERIOR":"No marca notorias diferencias, pero por juventud, hay que seguir observando más adelante."}'),
('0786bef5-2b4f-4197-b59d-92a23b7caf86','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('0c2eb7ca-cf28-4eb9-8f62-3fd6b8649baf','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('0c635e41-c117-4c09-a46a-e955552d4a2a','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO"}'),
('0c9d03d8-0fbe-4e23-907a-79634796e99c','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_INTERIOR":"PRIMERA EXPERIENCIA EN EL EXTRANJERO, VIENE DESTACANDO CON LEONES."}'),
('13809fea-2d5f-4164-b414-617d791a1d2d','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE"}'),
('1532f72d-39db-4d54-8a99-2aad18c4ae4f','{"valoracion":"4.INTERESANTE"}'),
('166b3697-029c-46b9-aa71-55c136778270','{"val_partido":"5. MUY IMPORTANTE","valoracion":"3.SEGUIR VIENDO","car_obs_INTERIOR":"Es un volante interior de lo mejor en cuanto a proyección de Chacarita, jugador que puede llegar por sorpresa al área y sorprender con algún remate o asistencia, en este partido estuvo apagado, al ser clásico se jugó un partido muy trabado, friccionado, no tuvo espacios, eso le jugó en contra y además se sintió que a un le falta asumir más responsabilidad en un entorno que exige mucha presión, por edad es un proyecto a tener en cuenta y seguir observando."}'),
('1b1ecabc-b5c6-41f3-b099-9ac28e36b8e1','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_LATERAL":"Lateral derecho que por edad tiene margen de mejora en todos los aspectos del juego, viene siendo de los más regulares del campeonato, hoy le tocó entrar desde la variante, puede aportar verticalidad por la banda, ganar raya de fondo y tirar centros que tiene que aún mejorar en la precisión, buena resistencia para el ida y vuelta, es un perfil que hay que seguir observando y tenerlo en el radar."}'),
('25376078-5fed-4ab0-bea5-10336be75e43','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_EXTREMO":"Extremo derecho que muestra condiciones interesantes sobre todo para encarar con regate en espacios cortos y hacer buenas conducciones pegado el balón al pie, eso si, aún le falta ganar más masa muscular para poder enfrentar de mejor manera los duelos físicos, lo tumban casi fácilmente, igual en la toma de decisiones aún debe ser más preciso, pero para ser jóven es un perfil a seguir observando y verlo cómo evoluciona más adelante."}'),
('25ec13f9-fd82-43fa-88f7-9e91f42791eb','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR"}'),
('2cee2138-a77f-423d-808a-5db0790dcb10','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR"}'),
('321587f9-987e-4b50-892f-7ff1b7dcf889','{"val_partido":"5. MUY IMPORTANTE","valoracion":"2.DESCARTAR"}'),
('32561e6d-efd2-433f-b631-ce1b8a5b2bf3','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('32625e94-9a13-4e16-b36b-f19ebe399dca','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('35d09199-69ac-497e-a867-69fa3f0f2958','{"val_partido":"5. MUY IMPORTANTE","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Central que destaca por su buen juego aéreo tanto en defensa cómo en fase ofensiva, tiene gol, hoy incluso anotó de cabeza en el clásico, defensivamente es seguro en los duelos sobre todo cuando el equipo está en bloque bajo, a campo abierto con jugadores más veloces puede llegar a sufrir, viene teniendo un torneo regular, interesante a seguir viendolo, pero sin ser prioridad."}'),
('3982a445-40d9-4a77-bacc-140156362f24','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('3c01ecaa-bb88-4785-a8ee-73453b1f6f85','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_EXTREMO":"SE CARACTERIZA POR SUS DUELOS EN BANDA, RECORTE HACIA DENTRO Y REMATES. EN ESTE PARTIDO HIZO UN GOL."}'),
('44ff18ac-4d63-47c0-8274-7620bbc4ad44','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
