('a5a75d47-5cf9-428c-98bf-1d65123e800b','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_PUNTA":"Definitivamente descartado."}'),
('a8e0030c-adf2-462c-b8ab-c590d9710f2e','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_CENTRAL":"Central rústico, falta de timming en el anticipo, suele ir behemente a los duelos y por edad. Descarte total."}'),
('ad245650-a5cd-4ac6-8b58-17be0cd61828','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"Mediocentro que suele aportar intensidad en los duelos y dinámica en la zona medular, pero no da calidad en los pases o aporta diferencias técnicas para que llame la atención, de todas formas no debería ser descarte total y seguir observando."}'),
