('dd0649a4-d8d0-48f0-8a6c-e44878c88b28','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"Mediocentro de buena dinámica y vigilancias defensivas, se suelta al ataque cuando tiene oportunidad y libertades, juega simple sin complicarse, un perfil a seguir observando."}'),
