('f130a9ef-dbca-4a24-a47b-fcd81f8fa530','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_EXTREMO":"Es criterioso por momentos con el balón, pero muy intermitente, hay mejores opciones en el mercado."}'),
('f24a000c-030b-4fe4-8f61-c5c7aafb74e4','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_EXTREMO":"RAPIDO BUENA CAPICDAD CREATIVA Y DE ASOCIARSE, PODRIA MAS DE MEDIAPUNTA, LIVIANO ATLETICAMENTE , RAPIDO CON REGISTROS TECNICOS SUPERIORES."}'),
