('3619c491-0838-41c9-8a60-fdff064c287f','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_MEDIAPUNTA":"Un jugador capaz de sostener el juego ofensivo de su equipo generando oportunidades mediante pases filtrados y avances por la zona media buscando oportunidad de definir."}'),
