('d0bc834d-8817-43cc-8fbb-fb4f33a06ad9','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE","car_obs_INTERIOR":"Volante que cuando se desempeña cómo interior destaca de mejor manera, al tener libertades para proyectarse al ataque y llegar a zona de finalización se siente más cómodo, posee muy buena resistencia para el ida y vuelta, más que ser un jugador técnico, es un jugador tácticamente funcional y con gran despliegue físico."}'),
('d1ada5c4-42ad-4a86-9f32-efb7b011f38d','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE"}'),
