('f48a1698-e954-4670-9af6-4e9bcbc9d4b8','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Complexion buena, sin embargo, lento, no muy acertado en ejecuiones con presiones. duelos aeros buenos."}'),
