('fa107d97-0ea2-41bd-876a-f50a50957251','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"5.FICHAR","car_obs_MEDIAPUNTA":"Mediapunta con gran visión de juego para filtrar pases entre líneas y asistir a sus compañeros, destacada calidad técnica en el pase y pegada en pelota quieta, jugador veterano que vale la pena tener en el equipo sin duda alguna."}'),
('ff592475-bccf-4347-b1d7-1ae4b3aff8d2','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO"}'),
('062b24eb-6440-4960-8d4b-e37827f88db1','{"val_partido":"3. RELEVANCIA NORMAL"}'),
